package co.sena.academic.adapter.out.persistence; import co.sena.academic.domain.model.LearningOutcome; public final class LearningOutcomeJpaMapper {private LearningOutcomeJpaMapper(){} public static LearningOutcomeJpaEntity toEntity(LearningOutcome v){return new LearningOutcomeJpaEntity(v.getId(),v.getCompetencyId(),v.getCode(),v.getDescription(),v.isActive(),v.getRowVersion(),v.getCreatedAt(),v.getCreatedBy(),v.getUpdatedAt(),v.getUpdatedBy(),v.getDeletedAt(),v.getDeletedBy());} public static LearningOutcome toDomain(LearningOutcomeJpaEntity v){return LearningOutcome.reconstitute(v.getId(),v.getCompetencyId(),v.getCode(),v.getDescription(),v.isActive(),v.getRowVersion(),v.getCreatedAt(),v.getCreatedBy(),v.getUpdatedAt(),v.getUpdatedBy(),v.getDeletedAt(),v.getDeletedBy());}}
